
.battleui {
  width: 100%;
  max-width: 720px;
  margin: 0 auto;
  font-family: var(--font-archive, inherit);
  color: var(--c-text, #e8e6e3);
}

.bu-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 14px;
  background: linear-gradient(120deg, rgba(224, 82, 94, 0.18), rgba(224, 82, 94, 0.05));
  border-bottom: 1px solid var(--c-accent-soft, #553a3a);
}

.bu-title {
  font-size: 15px;
  font-weight: 800;
  color: var(--c-accent, #e0525e);
}

.bu-state {
  font-size: 12px;
  padding: 2px 10px;
  border-radius: 999px;
  background: #ffffff10;
  color: var(--c-text-muted, #b8b4ae);
}

.bu-state.进行中 {
  color: var(--c-accent, #e0525e);
  background: var(--c-accent-soft, #553a3a);
}

.bu-state.已结算 {
  color: var(--c-success, #59c98d);
}

.bu-empty {
  padding: 28px 14px;
  text-align: center;
  color: var(--c-text-muted, #b8b4ae);
  font-size: 13px;
}

.bu-empty .dim {
  font-size: 11px;
  opacity: 0.65;
  margin-top: 6px;
}

.bu-schedule {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  padding: 10px 14px;
  font-size: 12px;
  color: var(--c-text-muted, #b8b4ae);
}

.bu-s-label {
  font-weight: 700;
  color: var(--c-gold, #d9a441);
}

.bu-s-item {
  padding: 2px 8px;
  border-radius: 6px;
  background: #ffffff08;
}
